type Row = { customer: string; calls: number; overage: number }

const palette = {
  background: '#fafbfc',
  surface: '#ffffff',
  text: '#1f2937',
  textMuted: '#6b7280',
  accent: '#3b82f6',
  success: '#10b981',
  warning: '#f59e0b',
  danger: '#ef4444',
  border: '#e5e7eb',
}

export default function Usage({ rows }: { rows: Row[] }) {
  const totalCalls = rows.reduce((n, r) => n + r.calls, 0)
  const totalOverage = rows.reduce((n, r) => n + r.overage, 0)
  const hasOverage = totalOverage > 0

  return (
    <div style={{
      padding: '32px',
      fontFamily: '"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
      background: palette.background,
      minHeight: '100vh',
    }}>
      {/* Header */}
      <div style={{ marginBottom: '40px' }}>
        <h1 style={{
          fontSize: '28px',
          fontWeight: '700',
          margin: '0 0 8px 0',
          color: palette.text,
          letterSpacing: '-0.5px',
        }}>
          Usage Dashboard
        </h1>
        <p style={{
          fontSize: '14px',
          color: palette.textMuted,
          margin: 0,
        }}>
          Current month overview
        </p>
      </div>

      {/* Key Metrics Grid */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
        gap: '20px',
        marginBottom: '40px',
      }}>
        {/* Calls Metric */}
        <div style={{
          background: palette.surface,
          border: `2px solid ${palette.border}`,
          borderRadius: '12px',
          padding: '24px',
          boxShadow: '0 1px 3px rgba(0, 0, 0, 0.05)',
        }}>
          <div style={{
            fontSize: '12px',
            fontWeight: '600',
            color: palette.textMuted,
            textTransform: 'uppercase',
            letterSpacing: '0.5px',
            marginBottom: '12px',
          }}>
            Total API Calls
          </div>
          <div style={{
            fontSize: '36px',
            fontWeight: '700',
            color: palette.accent,
            marginBottom: '12px',
            fontVariantNumeric: 'tabular-nums',
          }}>
            {totalCalls.toLocaleString()}
          </div>
          <div style={{
            fontSize: '13px',
            color: palette.textMuted,
            paddingTop: '12px',
            borderTop: `1px solid ${palette.border}`,
          }}>
            Across {rows.length} customer{rows.length !== 1 ? 's' : ''}
          </div>
        </div>

        {/* Overage Metric */}
        <div style={{
          background: palette.surface,
          border: `2px solid ${hasOverage ? palette.danger : palette.border}`,
          borderRadius: '12px',
          padding: '24px',
          boxShadow: `0 1px 3px rgba(0, 0, 0, 0.05)${hasOverage ? ', 0 0 16px rgba(239, 68, 68, 0.08)' : ''}`,
        }}>
          <div style={{
            fontSize: '12px',
            fontWeight: '600',
            color: palette.textMuted,
            textTransform: 'uppercase',
            letterSpacing: '0.5px',
            marginBottom: '12px',
          }}>
            Overage Fees
          </div>
          <div style={{
            fontSize: '36px',
            fontWeight: '700',
            color: hasOverage ? palette.danger : palette.success,
            marginBottom: '12px',
            fontVariantNumeric: 'tabular-nums',
          }}>
            ${totalOverage.toLocaleString()}
          </div>
          {hasOverage && (
            <div style={{
              fontSize: '13px',
              color: palette.danger,
              paddingTop: '12px',
              borderTop: `1px solid ${palette.border}`,
            }}>
              ⚠ From {rows.filter(r => r.overage > 0).length} customer{rows.filter(r => r.overage > 0).length !== 1 ? 's' : ''}
            </div>
          )}
          {!hasOverage && (
            <div style={{
              fontSize: '13px',
              color: palette.success,
              paddingTop: '12px',
              borderTop: `1px solid ${palette.border}`,
            }}>
              ✓ All customers within quota
            </div>
          )}
        </div>

        {/* Customer Count Metric */}
        <div style={{
          background: palette.surface,
          border: `2px solid ${palette.border}`,
          borderRadius: '12px',
          padding: '24px',
          boxShadow: '0 1px 3px rgba(0, 0, 0, 0.05)',
        }}>
          <div style={{
            fontSize: '12px',
            fontWeight: '600',
            color: palette.textMuted,
            textTransform: 'uppercase',
            letterSpacing: '0.5px',
            marginBottom: '12px',
          }}>
            Active Customers
          </div>
          <div style={{
            fontSize: '36px',
            fontWeight: '700',
            color: palette.success,
            marginBottom: '12px',
            fontVariantNumeric: 'tabular-nums',
          }}>
            {rows.length}
          </div>
          <div style={{
            fontSize: '13px',
            color: palette.textMuted,
            paddingTop: '12px',
            borderTop: `1px solid ${palette.border}`,
          }}>
            Generating usage
          </div>
        </div>
      </div>

      {/* Customer Details Table */}
      <div style={{
        background: palette.surface,
        border: `1px solid ${palette.border}`,
        borderRadius: '12px',
        overflow: 'hidden',
        boxShadow: '0 1px 3px rgba(0, 0, 0, 0.05)',
      }}>
        <div style={{
          padding: '24px',
          borderBottom: `1px solid ${palette.border}`,
        }}>
          <h2 style={{
            fontSize: '16px',
            fontWeight: '600',
            margin: 0,
            color: palette.text,
          }}>
            Customer Usage Breakdown
          </h2>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <table style={{
            width: '100%',
            borderCollapse: 'collapse',
            fontSize: '14px',
          }}>
            <thead>
              <tr style={{ background: palette.background, borderBottom: `2px solid ${palette.border}` }}>
                <th style={{
                  padding: '16px 24px',
                  textAlign: 'left',
                  fontWeight: '600',
                  color: palette.textMuted,
                  fontSize: '12px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                }}>
                  Customer
                </th>
                <th style={{
                  padding: '16px 24px',
                  textAlign: 'right',
                  fontWeight: '600',
                  color: palette.textMuted,
                  fontSize: '12px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                }}>
                  API Calls
                </th>
                <th style={{
                  padding: '16px 24px',
                  textAlign: 'right',
                  fontWeight: '600',
                  color: palette.textMuted,
                  fontSize: '12px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                }}>
                  Overage
                </th>
                <th style={{
                  padding: '16px 24px',
                  textAlign: 'center',
                  fontWeight: '600',
                  color: palette.textMuted,
                  fontSize: '12px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                }}>
                  Status
                </th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, idx) => {
                const hasOverageForRow = r.overage > 0
                return (
                  <tr
                    key={r.customer}
                    style={{
                      borderBottom: `1px solid ${palette.border}`,
                      background: hasOverageForRow ? 'rgba(239, 68, 68, 0.02)' : undefined,
                      transition: 'background-color 200ms ease',
                    }}
                    onMouseEnter={(e) => {
                      if (!hasOverageForRow) {
                        e.currentTarget.style.background = 'rgba(59, 130, 246, 0.02)'
                      }
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.background = hasOverageForRow ? 'rgba(239, 68, 68, 0.02)' : undefined
                    }}
                  >
                    <td style={{
                      padding: '16px 24px',
                      color: palette.text,
                      fontWeight: '500',
                    }}>
                      {r.customer}
                    </td>
                    <td style={{
                      padding: '16px 24px',
                      textAlign: 'right',
                      color: palette.text,
                      fontVariantNumeric: 'tabular-nums',
                    }}>
                      {r.calls.toLocaleString()}
                    </td>
                    <td style={{
                      padding: '16px 24px',
                      textAlign: 'right',
                      color: hasOverageForRow ? palette.danger : palette.text,
                      fontWeight: hasOverageForRow ? '600' : '400',
                      fontVariantNumeric: 'tabular-nums',
                    }}>
                      ${r.overage.toLocaleString()}
                    </td>
                    <td style={{
                      padding: '16px 24px',
                      textAlign: 'center',
                    }}>
                      {hasOverageForRow ? (
                        <span style={{
                          display: 'inline-block',
                          padding: '4px 12px',
                          background: 'rgba(239, 68, 68, 0.1)',
                          color: palette.danger,
                          borderRadius: '6px',
                          fontSize: '12px',
                          fontWeight: '600',
                        }}>
                          ⚠ Over quota
                        </span>
                      ) : (
                        <span style={{
                          display: 'inline-block',
                          padding: '4px 12px',
                          background: 'rgba(16, 185, 129, 0.1)',
                          color: palette.success,
                          borderRadius: '6px',
                          fontSize: '12px',
                          fontWeight: '600',
                        }}>
                          ✓ On quota
                        </span>
                      )}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

