import { useEffect, useRef } from 'react'
import { trackEvent } from '../lib/analytics'

export default function Landing({ planTier = 'free' }: { planTier?: string }) {
  const buttonRef = useRef<HTMLButtonElement>(null)
  const observedRef = useRef(false)

  useEffect(() => {
    if (!buttonRef.current || observedRef.current) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !observedRef.current) {
          observedRef.current = true
          trackEvent('cta_seen', { planTier })
        }
      },
      { threshold: 0.1 }
    )

    observer.observe(buttonRef.current)
    return () => observer.disconnect()
  }, [planTier])

  return (
    <main style={{ padding: 16, fontFamily: 'system-ui' }}>
      <h1 style={{ fontSize: 24 }}>Meterly</h1>
      <p style={{ fontSize: 14, color: '#666' }}>
        Usage metering for API companies. Track, rate and bill every call.
      </p>
      <button ref={buttonRef} style={{ background: '#3b82f6', color: '#fff', padding: 8 }}>
        Start free
      </button>
      <section>
        <h2 style={{ fontSize: 18 }}>Why teams switch</h2>
        <ul>
          <li>Per-second aggregation</li>
          <li>ExamplePay and ExampleSubscriptions sync</li>
          <li>Usage alerts before the invoice</li>
        </ul>
      </section>
    </main>
  )
}

