export function PlanPicker({ onChoose }: { onChoose: (plan: string) => Promise<void> }) {
  const [plan, setPlan] = useState('starter')
  const [pending, setPending] = useState(false)

  async function submit() {
    if (pending) return
    setPending(true)
    try {
      await onChoose(plan)
    } finally {
      setPending(false)
    }
  }
